CREATE TABLE IF NOT EXISTS "operatingcosts" (
  "id" INTEGER PRIMARY KEY NOT NULL,
  "excelcostid" VARCHAR(64),
  "excelkey" VARCHAR(320),
  "txdate" TIMESTAMP NOT NULL,
  "payee" VARCHAR(320),
  "expenseaccount" VARCHAR(320),
  "description" TEXT,
  "amount" NUMERIC(12,2) NOT NULL,
  "currency" VARCHAR(8) NOT NULL DEFAULT 'AED',
  "paidfrom" VARCHAR(128),
  "reference" VARCHAR(128),
  "rawcosttype" VARCHAR(128),
  "costcenter" VARCHAR(128),
  "category" VARCHAR(32) NOT NULL,
  "classification" VARCHAR(32) NOT NULL,
  "notes" TEXT,
  "createdat" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedat" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('operatingcosts','id'), GREATEST((SELECT COALESCE(MAX(id),1) FROM "operatingcosts"),1), true);
